<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {runs} from '../stores/runs';import PageHeading from '../components/common/PageHeading.vue';import KrigingMetrics from '../components/KrigingMetrics.vue';import SpatialMap from '../components/SpatialMap.vue';import VariogramPlot from '../components/VariogramPlot.vue';import WarningNotes from '../components/WarningNotes.vue';const mode=ref<'value'|'sd'>('value');onMounted(runs.load);const result=computed(()=>(runs.items.value.find(r=>r.id==='demo-run')||runs.items.value.find(r=>r.status==='completed'))?.result)</script><template><PageHeading index="00 / 地块总览" title="推断一片地，也说明模型知道多少。" note="米制采样点的经验半变异函数锁定后，再解普通克里金系统。空间随机场方差不是真实误差，不以全量拟合伪作LOO验证。"/><template v-if="result"><WarningNotes :rows="result.warnings"/><KrigingMetrics :result="result"/><div class="field-layout"><section><div class="section-heading"><h2>地块采样与待估点</h2><label>地图着色<select v-model="mode"><option value="value">预测含水率</option><option value="sd">空间标准差</option></select></label></div><SpatialMap :points="result.points" :predictions="result.kriging.predictions" :mode="mode"/><a href="#/results" class="action-link">打开25点预测与权重底稿 ↗</a></section><aside class="field-note"><p class="eyebrow">VARIOGRAM NOTE</p><h2>距离如何进入模型</h2><VariogramPlot :result="result"/><p>箱内采用平均实际距离与0.5×读数差平方；拟合残差按点对计数加权。固定nugget={{result.model.nugget}}。</p><p>拟合触界会明确提醒。给定模型下的方差只反映空间随机场假设，不替代现场复测。</p></aside></div></template></template>
